insert into public.vocabulary_items
(vocabulary_id,term,part_of_speech,core_meaning,senses,word_family,collocations,status)
values
('vocab_membership','membership','noun','the state of belonging to a group, club or organisation','[{"senseId":"membership_1","meaning":"the state of belonging to a group, club or organisation","acceptedParaphrases":["the state of belonging to a group","the fact of being part of a club"],"masteryContexts":[{"contextId":"u7_31_membership_meaning","text":"After the interview, she was invited to apply for membership of the national youth orchestra.","meaning":"the state of belonging to a group","wrongMeanings":["the rules that a group must follow","the leader who guides a group","the money that a group collects"]},{"contextId":"u7_31_membership_paraphrase","text":"Annual membership gives students free entry to the museum and discounts in the shop.","meaning":"the right to belong to an organisation","wrongMeanings":["the cost of travelling to an organisation","the history of an organisation","the building where an organisation works"]}],"situationDistractors":["A girl filled in a form and paid a small fee so that she could join the local swimming club.","A boy showed a card at the entrance that proved he belonged to the library.","A man renewed his place in the film society for another year.","The cook added salt to the soup and stirred it slowly.","The coach drove the team to the stadium before the match.","A girl painted a picture of the harbour for her art lesson."],"gapDistractors":[{"contextId":"u7_31_membership_gap_1","answer":"membership","wrong":["recipe","harbour","ticket"]},{"contextId":"u7_31_membership_gap_2","answer":"membership","wrong":["neighbour","umbrella","museum"]},{"contextId":"u7_31_membership_gap_3","answer":"membership","wrong":["souvenir","carpet","staircase"]}],"spellingErrors":["membersip","memebership","membershipp","memberchip","mebership","membarship"],"masteryPassages":[{"passageId":"u7_31_membership_passage_1","contextId":"u7_31_membership_gap_1","text":"The gym offered a special price to young people. Ahmed paid a small fee and received a card that proved his ____, so that he could use the swimming pool and the sports hall whenever he liked.","answer":"membership"},{"passageId":"u7_31_membership_passage_2","contextId":"u7_31_membership_gap_2","text":"Employers like to see activities on a CV that show teamwork. Your ____ of a school team or a youth club can be good evidence that you work well with others.","answer":"membership"}],"contextDependentParaphrases":[],"wrongParaphrases":["place where a club meets","list of rules for a club","fee paid only once"],"misleadingDistractors":["a place where a club holds its meetings","a list of the rules for a club","a fee that is paid only once"],"teacherNote":"Noun: the state of belonging to a group, club or organisation (apply for membership, membership of a club). It is usually uncountable here. Boundary: membership is the state or the right of belonging; the members are the people who belong, so the two should not be confused."}]'::jsonb,'[]'::jsonb,'["apply for membership","membership of a club","annual membership"]'::jsonb,'live'),
('vocab_certificate','certificate','noun','an official document that shows that a person has passed an exam or finished a course','[{"senseId":"certificate_1","meaning":"an official document that shows that a person has passed an exam or finished a course","acceptedParaphrases":["official paper that proves you passed","document showing a course was completed"],"masteryContexts":[{"contextId":"u7_32_certificate_meaning","text":"She showed the interviewer her first-aid certificate and her swimming award.","meaning":"an official document proving a skill","wrongMeanings":["a written promise to pay money","a short note of thanks","a list of exam questions"]},{"contextId":"u7_32_certificate_paraphrase","text":"Students who attend every lesson will be given a certificate at the end of the programme.","meaning":"an official paper showing a course is complete","wrongMeanings":["a free ticket to an event","a private letter from the teacher","a timetable of future lessons"]}],"situationDistractors":["A girl received a printed page with her name on it after passing the first-aid course.","A boy proudly put the paper that confirmed his exam result in a folder for job interviews.","A woman handed an official document to the college to prove that she had completed her training.","The conductor raised his arms and the orchestra began to play.","A boy swept the classroom floor after the last lesson of the day.","The farmer drove the tractor across the muddy field."],"gapDistractors":[{"contextId":"u7_32_certificate_gap_1","answer":"certificate","wrong":["recipe","harbour","ticket"]},{"contextId":"u7_32_certificate_gap_2","answer":"certificate","wrong":["neighbour","umbrella","museum"]},{"contextId":"u7_32_certificate_gap_3","answer":"certificate","wrong":["souvenir","carpet","staircase"]}],"spellingErrors":["certifficate","certeficate","sertificate","certificat","certifcate","certificete"],"wordFamilyForms":[{"form":"certificate","partOfSpeech":"noun","example":"The college sends a certificate to every student who completes the course.","pedagogicallyUseful":true},{"form":"certify","partOfSpeech":"verb","example":"The doctor will certify that the applicant is fit to work.","pedagogicallyUseful":true,"altExample":"The teacher must certify that each student has attended at least ninety per cent of the lessons."},{"form":"certified","partOfSpeech":"adjective","example":"Only certified instructors are allowed to teach the diving class.","pedagogicallyUseful":true,"altExample":"The company hired a certified electrician to check the wiring in the new office."}],"masteryPassages":[{"passageId":"u7_32_certificate_passage_1","contextId":"u7_32_certificate_gap_1","text":"After six weeks of evening classes, the group sat a short practical test. Everyone who passed received a ____ signed by the instructor, which they could show to future employers.","answer":"certificate"},{"passageId":"u7_32_certificate_passage_2","contextId":"u7_32_certificate_gap_2","text":"The advertisement said that applicants must hold a valid driving licence and a first-aid ____. Without these documents, even the most experienced person could not be considered.","answer":"certificate"}],"contextDependentParaphrases":[],"wrongParaphrases":["written promise to pay money","short note of thanks","list of exam questions"],"misleadingDistractors":["a written promise to pay money later","a short letter that thanks a company","a list of the questions in an exam"],"teacherNote":"Noun: an official document that shows that someone has passed an exam, finished a course or reached a standard (a first-aid certificate, a certificate of attendance). Boundary: a certificate is the document; the qualification is the achievement it proves. The verb certify and the adjective certified are taught in the Word Family pathway."}]'::jsonb,'["certify","certified"]'::jsonb,'["a first-aid certificate","a certificate of achievement","receive a certificate"]'::jsonb,'live'),
('vocab_qualification_7','qualification','noun','a quality, skill or achievement that makes a person suitable for a particular job or role','[{"senseId":"qualification_7_1","meaning":"a quality, skill or achievement that makes a person suitable for a particular job or role","acceptedParaphrases":["skill that makes someone suitable for a job","quality needed to do a role well"],"masteryContexts":[{"contextId":"u7_33_qualification_7_meaning","text":"Patience is probably the most important qualification for anyone who wants to teach young children.","meaning":"a skill that makes someone suitable for a role","wrongMeanings":["a habit that makes someone unpopular in a role","a reward that someone receives for a role","a rule that someone must follow in a role"]},{"contextId":"u7_33_qualification_7_paraphrase","text":"The advertisement said that fluency in two languages was a useful qualification for the post.","meaning":"a skill that makes a person suitable for a job","wrongMeanings":["a fault that makes a person unsuitable for a job","a cost that a person pays to get a job","a day that a person spends at a job"]}],"situationDistractors":["The advertisement stated that a person who could speak Arabic would be especially suitable for the job.","A manager said that good communication was the first thing she looked for in a new receptionist.","A teacher explained that the main thing a lifeguard needs is to be a strong swimmer.","The librarian stamped each book and put it on the trolley.","A boy tied his shoelaces and then ran to catch the school bus.","Heavy rain fell on the roof of the bus shelter all afternoon."],"gapDistractors":[{"contextId":"u7_33_qualification_7_gap_1","answer":"qualification","wrong":["recipe","harbour","ticket"]},{"contextId":"u7_33_qualification_7_gap_2","answer":"qualification","wrong":["neighbour","umbrella","museum"]},{"contextId":"u7_33_qualification_7_gap_3","answer":"qualification","wrong":["souvenir","carpet","staircase"]}],"spellingErrors":["qualifiation","qualifcation","qualificashion","quallification","qualificaton","qualafication"],"wordFamilyForms":[{"form":"qualification","partOfSpeech":"noun","example":"A friendly manner is a useful qualification for working with customers.","pedagogicallyUseful":true},{"form":"qualify","partOfSpeech":"verb","example":"You must pass the exam before you qualify as a teacher.","pedagogicallyUseful":true,"altExample":"Players must win two matches in order to qualify for the final."},{"form":"qualified","partOfSpeech":"adjective","example":"The school is looking for a qualified science teacher.","pedagogicallyUseful":true,"altExample":"Only a fully qualified nurse can give this treatment in the hospital."}],"masteryPassages":[{"passageId":"u7_33_qualification_7_passage_1","contextId":"u7_33_qualification_7_gap_1","text":"The advertisement for the hotel receptionist did not ask for any exam results. The manager said that the most important ____ was a friendly manner, because guests notice the first person they meet.","answer":"qualification"},{"passageId":"u7_33_qualification_7_passage_2","contextId":"u7_33_qualification_7_gap_2","text":"To work as a lifeguard, you must be a strong swimmer. For the manager, this was the first ____ that he looked for, and no certificate could replace it.","answer":"qualification"}],"contextDependentParaphrases":[],"wrongParaphrases":["mistake that makes someone unsuitable","reward given at the end of a year","rule every worker must obey"],"misleadingDistractors":["a mistake that makes someone unsuitable for a job","a reward given at the end of a year","a rule that every worker must obey"],"teacherNote":"Unit 7 item (qualification_7), separate from the Unit 5 qualification item; it shares only the lexical spelling list. Sense in this unit: a quality, skill or achievement that makes a person suitable for a particular job or role (the main qualification for the post). Boundary: the plural qualifications (also a target in this unit) means the collection of exam results and training on a CV; use the singular for one required quality or skill. The verb qualify and the adjective qualified are taught in the Word Family pathway."}]'::jsonb,'["qualify","qualified"]'::jsonb,'["an essential qualification","the main qualification for","lack a qualification"]'::jsonb,'live'),
('vocab_experience','experience','noun','knowledge and skill gained from doing something for a period of time','[{"senseId":"experience_1","meaning":"knowledge and skill gained from doing something for a period of time","acceptedParaphrases":["knowledge gained by doing something","skill learned from practice over time"],"masteryContexts":[{"contextId":"u7_34_experience_meaning","text":"Her experience as a volunteer at the hospital helped her to answer the interviewer’s questions with confidence.","meaning":"knowledge and skill gained from doing something","wrongMeanings":["a feeling of surprise at a new event","a plan for working in a hospital","a fee paid to work in a hospital"]},{"contextId":"u7_34_experience_paraphrase","text":"The company prefers candidates with at least a year of work experience in sales.","meaning":"skill gained over time in a job","wrongMeanings":["a test taken at the start of a job","a holiday taken in the middle of a job","a payment received at the end of a job"]}],"situationDistractors":["A girl explained that she had spent two summers helping at a nursery and had learned how to look after young children.","A man told the panel that he had worked as a waiter for five years and could deal with most customer problems.","A student described how a month in a local newspaper office had taught her to meet deadlines.","The conductor raised his arms and the orchestra began to play.","A boy swept the classroom floor after the last lesson of the day.","The farmer drove the tractor across the muddy field."],"gapDistractors":[{"contextId":"u7_34_experience_gap_1","answer":"experience","wrong":["recipe","harbour","ticket"]},{"contextId":"u7_34_experience_gap_2","answer":"experience","wrong":["neighbour","umbrella","museum"]},{"contextId":"u7_34_experience_gap_3","answer":"experience","wrong":["souvenir","carpet","staircase"]}],"spellingErrors":["experiance","experiense","expereince","experence","exprience","experiecne"],"wordFamilyForms":[{"form":"experience","partOfSpeech":"noun","example":"Previous experience in a similar job will help you to settle in quickly.","pedagogicallyUseful":true},{"form":"experienced","partOfSpeech":"adjective","example":"The company is looking for an experienced manager to lead the new department.","pedagogicallyUseful":true,"altExample":"An experienced teacher knows how to keep a lively class under control."},{"form":"inexperienced","partOfSpeech":"adjective","example":"Employers must train inexperienced workers carefully before they deal with customers.","pedagogicallyUseful":true,"altExample":"She was young and inexperienced, but she was willing to learn quickly."}],"masteryPassages":[{"passageId":"u7_34_experience_passage_1","contextId":"u7_34_experience_gap_1","text":"Karim had no certificates in cooking, but he had spent three summers working in his uncle’s café. The chef decided that this practical ____ was more valuable than a course certificate.","answer":"experience"},{"passageId":"u7_34_experience_passage_2","contextId":"u7_34_experience_gap_2","text":"Many school leavers feel that employers ask for a lot of ____ from people who have never had a job. Voluntary work and holiday jobs can help young people to gain it.","answer":"experience"}],"contextDependentParaphrases":[],"wrongParaphrases":["sudden feeling of fear","plan for future work","exam on a skill"],"misleadingDistractors":["a sudden feeling of fear or surprise","a plan for doing something in the future","an exam that tests a particular skill"],"teacherNote":"Noun: knowledge and skill gained from doing a job or activity over a period of time (work experience, previous experience). In this sense it is uncountable. The other sense of experience, an event that happens to you (a memorable experience), is not taught here. Related forms (experienced, inexperienced) are taught in the Word Family pathway."}]'::jsonb,'["experienced","inexperienced"]'::jsonb,'["work experience","gain experience","previous experience"]'::jsonb,'live'),
('vocab_confidence_7','confidence','noun','the feeling that you can do something well, or that you can trust your own ability','[{"senseId":"confidence_7_1","meaning":"the feeling that you can do something well, or that you can trust your own ability","acceptedParaphrases":["feeling that you can do it well","trust in your own ability"],"masteryContexts":[{"contextId":"u7_35_confidence_7_meaning","text":"Smiling and speaking clearly can give a nervous candidate more confidence in the first minute of an interview.","meaning":"the feeling that you can do something well","wrongMeanings":["the fear that you may do something badly","the wish that you could do something else","the habit of doing something every day"]},{"contextId":"u7_35_confidence_7_paraphrase","text":"Her confidence in her own skills was clear from the way she explained her ideas to the panel.","meaning":"trust in your own ability","wrongMeanings":["doubt about your own ability","jealousy of other people’s ability","respect for other people’s ability"]}],"situationDistractors":["A boy stood up straight, looked at the panel and answered each question without hesitating.","A girl told herself calmly that she had prepared well and knew the answers.","A man walked into the room with a smile and shook everybody’s hand firmly.","The cleaner locked the office and switched off all the lights.","Two students carried a heavy box of books up the stairs.","The receptionist watered the plants beside the main entrance."],"gapDistractors":[{"contextId":"u7_35_confidence_7_gap_1","answer":"confidence","wrong":["recipe","harbour","ticket"]},{"contextId":"u7_35_confidence_7_gap_2","answer":"confidence","wrong":["neighbour","umbrella","museum"]},{"contextId":"u7_35_confidence_7_gap_3","answer":"confidence","wrong":["souvenir","carpet","staircase"]}],"spellingErrors":["confidance","confedence","confidense","confidnce","conffidence","confindence"],"wordFamilyForms":[{"form":"confidence","partOfSpeech":"noun","example":"Good preparation gives you confidence on the day of the interview.","pedagogicallyUseful":true},{"form":"confident","partOfSpeech":"adjective","example":"He felt confident that he could answer any question about teamwork.","pedagogicallyUseful":true,"altExample":"A confident speaker looks at the audience and speaks at a steady pace."},{"form":"confidently","partOfSpeech":"adverb","example":"She walked confidently into the room and shook hands with the panel.","pedagogicallyUseful":true,"altExample":"The students presented their results confidently, even though they were nervous at first."}],"masteryPassages":[{"passageId":"u7_35_confidence_7_passage_1","contextId":"u7_35_confidence_7_gap_1","text":"Nadia used to look at the floor when she spoke to adults. After practising interview questions every evening for two weeks, she walked into the room and looked the panel in the eye with new ____.","answer":"confidence"},{"passageId":"u7_35_confidence_7_passage_2","contextId":"u7_35_confidence_7_gap_2","text":"Some candidates have excellent skills but do not show them because they lack ____. Smiling, sitting up straight and taking a deep breath before speaking can help.","answer":"confidence"}],"contextDependentParaphrases":[],"wrongParaphrases":["fear that something will go wrong","secret told to a friend","habit practised for years"],"misleadingDistractors":["a fear that something will go wrong","a secret that you tell only a friend","a habit that you have practised for years"],"teacherNote":"Unit 7 item (confidence_7), separate from the Unit 6 confidence item; it shares only the lexical spelling list. Sense in this unit: the feeling that you can do something well, especially when speaking to an interview panel (have confidence, lack confidence, confidence in yourself). Boundary: confidence is a healthy belief in your ability; it is not the same as arrogance, which is showing too much belief in yourself."}]'::jsonb,'["confident","confidently"]'::jsonb,'["build confidence","lose confidence","speak with confidence"]'::jsonb,'live'),
('vocab_anxious_7','anxious','adjective','feeling worried or nervous about something that is going to happen','[{"senseId":"anxious_7_1","meaning":"feeling worried or nervous about something that is going to happen","acceptedParaphrases":["worried about what may happen","nervous and uneasy"],"masteryContexts":[{"contextId":"u7_36_anxious_7_meaning","text":"Daniel felt anxious as he waited outside the room, repeating his answers in his head.","meaning":"worried about what may happen","wrongMeanings":["pleased about what has happened","bored by what is happening","angry about what will happen"]},{"contextId":"u7_36_anxious_7_paraphrase","text":"The teacher told the anxious students that the test would only check what they had already learned.","meaning":"nervous and worried about a future event","wrongMeanings":["excited and keen to start an event","tired and unwilling to join an event","angry and eager to leave an event"]}],"situationDistractors":["A girl kept checking her watch and twisting her fingers as the clock moved towards her interview time.","A boy could not sleep the night before his exam because he kept imagining what might go wrong.","A woman asked three times whether her documents were in the right order before she went in.","A boy tied his shoelaces and then ran to catch the school bus.","The librarian stamped each book and put it on the trolley.","Heavy rain fell on the roof of the bus shelter all afternoon."],"gapDistractors":[{"contextId":"u7_36_anxious_7_gap_1","answer":"anxious","wrong":["frozen","rectangular","wooden"]},{"contextId":"u7_36_anxious_7_gap_2","answer":"anxious","wrong":["enormous","furious","distant"]},{"contextId":"u7_36_anxious_7_gap_3","answer":"anxious","wrong":["bitter","crowded","careless"]}],"spellingErrors":["anxous","anxius","anxcious","ancious","anxiuos","anxsious"],"wordFamilyForms":[{"form":"anxious","partOfSpeech":"adjective","example":"Many applicants feel anxious when they wait outside the interview room.","pedagogicallyUseful":true},{"form":"anxiety","partOfSpeech":"noun","example":"Slow breathing can help to reduce anxiety before a speaking test.","pedagogicallyUseful":true,"altExample":"The head teacher spoke to parents about the anxiety that some students feel before exams."},{"form":"anxiously","partOfSpeech":"adverb","example":"She waited anxiously by the telephone for the result of the interview.","pedagogicallyUseful":true,"altExample":"The candidates sat anxiously in the corridor while the panel discussed the first applicant."}],"masteryPassages":[{"passageId":"u7_36_anxious_7_passage_1","contextId":"u7_36_anxious_7_gap_1","text":"Priya had prepared for the interview for weeks, but as she walked into the building her hands began to shake and her mouth felt dry. She was so ____ that she could hardly remember her own name.","answer":"anxious"},{"passageId":"u7_36_anxious_7_passage_2","contextId":"u7_36_anxious_7_gap_2","text":"The teacher noticed that several students were ____ about the speaking exam. She reminded them that nobody expected a perfect performance and that the examiner would be friendly.","answer":"anxious"}],"contextDependentParaphrases":[],"wrongParaphrases":["excited and keen to begin","bored and ready to leave","angry and unwilling to speak"],"misleadingDistractors":["excited and eager to begin","bored and ready to leave","angry and unwilling to speak"],"teacherNote":"Unit 7 item (anxious_7), separate from the Unit 4 anxious item; it shares only the lexical spelling list. Sense in this unit: feeling worried or nervous about something that is going to happen, such as an interview or a test (anxious about). Boundary: anxious is stronger than a little nervous; it describes a worry that can affect how you behave. The related noun anxiety is taught in the Word Family pathway."}]'::jsonb,'["anxiety","anxiously"]'::jsonb,'["feel anxious","anxious about","an anxious wait"]'::jsonb,'live'),
('vocab_expertise','expertise','noun','a high level of special knowledge or skill in a particular subject or activity','[{"senseId":"expertise_1","meaning":"a high level of special knowledge or skill in a particular subject or activity","acceptedParaphrases":["special knowledge in a subject","high level of skill in a field"],"masteryContexts":[{"contextId":"u7_37_expertise_meaning","text":"The college invited an engineer with great expertise in renewable energy to talk to the class.","meaning":"a high level of special knowledge","wrongMeanings":["a short visit to a place","a brief interest in a subject","a long history of a subject"]},{"contextId":"u7_37_expertise_paraphrase","text":"Because of her expertise in teaching languages, the school asked her to train the new staff.","meaning":"a high level of skill in a field","wrongMeanings":["a basic knowledge of the first steps","a dislike of repeating the same task","a plan to learn something new"]}],"situationDistractors":["A doctor who had studied heart problems for twenty years was asked to advise the hospital on a difficult case.","A woman who had designed bridges for many years explained the new plan to the committee.","A man who had taught chemistry for a long time helped the new teacher to prepare her lessons.","The cook added salt to the soup and stirred it slowly.","The coach drove the team to the stadium before the match.","A girl painted a picture of the harbour for her art lesson."],"gapDistractors":[{"contextId":"u7_37_expertise_gap_1","answer":"expertise","wrong":["recipe","harbour","ticket"]},{"contextId":"u7_37_expertise_gap_2","answer":"expertise","wrong":["neighbour","umbrella","museum"]},{"contextId":"u7_37_expertise_gap_3","answer":"expertise","wrong":["souvenir","carpet","staircase"]}],"spellingErrors":["expertice","experties","expertize","expertis","exspertise","experttise"],"masteryPassages":[{"passageId":"u7_37_expertise_passage_1","contextId":"u7_37_expertise_gap_1","text":"The school wanted to start a robotics club, but nobody on the staff knew how to build a robot. They invited an engineer with a lot of ____ to show the students what to do.","answer":"expertise"},{"passageId":"u7_37_expertise_passage_2","contextId":"u7_37_expertise_gap_2","text":"Experience and ____ are not the same thing. A person can work in an office for ten years, but a real specialist has studied one subject deeply and can solve problems that others cannot.","answer":"expertise"}],"contextDependentParaphrases":[],"wrongParaphrases":["general interest in many subjects","short course on basic skills","feeling of pride in work"],"misleadingDistractors":["a general interest in many subjects","a short course that teaches basic skills","a feeling of pride in your own work"],"teacherNote":"Noun: a high level of special knowledge or skill in a particular subject or activity (expertise in, technical expertise). It is uncountable and is usually followed by in. Boundary: expertise is deeper than experience; a person can have experience of a job without having expertise. It is spelled with -ise, not -ize."}]'::jsonb,'[]'::jsonb,'["expertise in","technical expertise","share your expertise"]'::jsonb,'live'),
('vocab_technique_7','technique','noun','a particular way of doing something that needs practice, such as speaking, playing or writing','[{"senseId":"technique_7_1","meaning":"a particular way of doing something that needs practice, such as speaking, playing or writing","acceptedParaphrases":["skilled way of doing something","particular method learned with practice"],"masteryContexts":[{"contextId":"u7_38_technique_7_meaning","text":"The coach taught the students a technique for answering difficult questions in a calm way.","meaning":"a particular skilled way of doing something","wrongMeanings":["a machine used to do something","a rule about doing something","a fear of doing something"]},{"contextId":"u7_38_technique_7_paraphrase","text":"Her technique for remembering names was to repeat each one aloud three times.","meaning":"a method that is practised and used","wrongMeanings":["a mistake that is repeated and noticed","a gift that is given and shared","a list that is written and posted"]}],"situationDistractors":["A teacher showed the class how to count to four while breathing in and out to calm their nerves.","A coach explained exactly how to hold the racket for a better serve.","A writer used a special method of planning her paragraphs on index cards.","The conductor raised his arms and the orchestra began to play.","A boy swept the classroom floor after the last lesson of the day.","The farmer drove the tractor across the muddy field."],"gapDistractors":[{"contextId":"u7_38_technique_7_gap_1","answer":"technique","wrong":["recipe","harbour","ticket"]},{"contextId":"u7_38_technique_7_gap_2","answer":"technique","wrong":["neighbour","umbrella","museum"]},{"contextId":"u7_38_technique_7_gap_3","answer":"technique","wrong":["souvenir","carpet","staircase"]}],"spellingErrors":["technic","techneque","tecnique","techniqe","techinique","tehnique"],"masteryPassages":[{"passageId":"u7_38_technique_7_passage_1","contextId":"u7_38_technique_7_gap_1","text":"Before going into the interview room, Tariq used a simple breathing ____ that his coach had taught him: he breathed in for four seconds and out for six. By the time he sat down, he felt much calmer.","answer":"technique"},{"passageId":"u7_38_technique_7_passage_2","contextId":"u7_38_technique_7_gap_2","text":"Good writers do not simply start writing. Many of them use a planning ____ such as writing the main idea of each paragraph on a small card before they begin the essay.","answer":"technique"}],"contextDependentParaphrases":[],"wrongParaphrases":["machine that makes work easier","mistake made when learning","plan for a whole year"],"misleadingDistractors":["a machine that makes work easier","a mistake made when learning","a plan for a whole year of work"],"teacherNote":"Unit 7 item (technique_7), separate from the Unit 6 technique item; it shares only the lexical spelling list. Sense in this unit: a particular skilled way of doing something that improves with practice (a breathing technique, a technique for answering questions). Boundary: a technique is one specific method; a strategy is the overall plan (strategy is also a target in this unit)."}]'::jsonb,'[]'::jsonb,'["a useful technique","a breathing technique","learn a technique"]'::jsonb,'live'),
('vocab_evaluate_7','evaluate','verb','to judge how good, useful or successful something is, after thinking about it carefully','[{"senseId":"evaluate_7_1","meaning":"to judge how good, useful or successful something is, after thinking about it carefully","acceptedParaphrases":["judge how good something is","think carefully about the value of"],"masteryContexts":[{"contextId":"u7_39_evaluate_7_meaning","text":"The teacher asked the students to evaluate their own performance in the mock interview.","meaning":"to judge how good something is","wrongMeanings":["to describe something in detail without giving an opinion","to copy something so that it looks the same","to practise something several times"]},{"contextId":"u7_39_evaluate_7_paraphrase","text":"The panel will evaluate each candidate on communication, teamwork and knowledge of the company.","meaning":"to judge how well someone has done","wrongMeanings":["to introduce someone to a company","to hire someone for a trial period","to ask someone to leave the room"]}],"situationDistractors":["A teacher read the speaking tests and gave each student marks for clarity, accuracy and confidence.","A manager compared three candidates against the list of skills and decided who had done best.","A student watched a recording of her practice interview and wrote down what had gone well and what had not.","The librarian stamped each book and put it on the trolley.","A boy tied his shoelaces and then ran to catch the school bus.","Heavy rain fell on the roof of the bus shelter all afternoon."],"gapDistractors":[{"contextId":"u7_39_evaluate_7_gap_1","answer":"evaluate","wrong":["announce","invent","advertise"]},{"contextId":"u7_39_evaluate_7_gap_2","answer":"evaluate","wrong":["decorate","translate","borrow"]},{"contextId":"u7_39_evaluate_7_gap_3","answer":"evaluate","wrong":["postpone","photograph","celebrate"]}],"spellingErrors":["evalute","evaluat","evalaute","evaluete","evluate","evalueate"],"masteryPassages":[{"passageId":"u7_39_evaluate_7_passage_1","contextId":"u7_39_evaluate_7_gap_1","text":"At the end of the practice interview, Sara’s teacher asked her to ____ her own performance. Sara listed three things she had done well and two things that she wanted to improve.","answer":"evaluate"},{"passageId":"u7_39_evaluate_7_passage_2","contextId":"u7_39_evaluate_7_gap_2","text":"Each candidate was given a score for communication, teamwork and knowledge. The panel used the same sheet to ____ everyone, so that the final decision would be fair.","answer":"evaluate"}],"contextDependentParaphrases":[],"wrongParaphrases":["to describe without giving a view","to repeat in order to remember","to ask for a change"],"misleadingDistractors":["to describe something without giving a view","to repeat something in order to remember it","to ask for something to be changed"],"teacherNote":"Unit 7 item (evaluate_7), separate from the Unit 3, Unit 5 and Unit 6 evaluate items; it shares only the lexical spelling list. Sense in this unit: to judge how good, useful or successful someone or something is after careful thought, for example when a panel assesses candidates. Boundary: evaluate is about judging quality using clear points; it is not the same as describe, which gives information without a judgement."}]'::jsonb,'[]'::jsonb,'["evaluate a candidate","evaluate your performance","carefully evaluate"]'::jsonb,'live'),
('vocab_organise','organise','verb','to arrange things in a sensible order, or to plan and prepare an event or activity','[{"senseId":"organise_1","meaning":"to arrange things in a sensible order, or to plan and prepare an event or activity","acceptedParaphrases":["arrange in a sensible order","plan and prepare carefully"],"masteryContexts":[{"contextId":"u7_40_organise_meaning","text":"Before the interview, Hana tried to organise her answers into three clear points.","meaning":"to arrange things in a sensible order","wrongMeanings":["to remove things from a list","to repeat things many times","to hide things from other people"]},{"contextId":"u7_40_organise_paraphrase","text":"The students decided to organise a careers evening for parents and local employers.","meaning":"to plan and prepare an event","wrongMeanings":["to cancel an event at the last minute","to join an event as a guest","to forget an event after it has finished"]}],"situationDistractors":["A girl wrote the three main points of her talk on a card and put them in order.","A group of students booked a room, sent invitations and printed a programme for a school fair.","A boy sorted his notes into folders, one for each subject.","The conductor raised his arms and the orchestra began to play.","A boy swept the classroom floor after the last lesson of the day.","The farmer drove the tractor across the muddy field."],"gapDistractors":[{"contextId":"u7_40_organise_gap_1","answer":"organise","wrong":["borrow","repair","forget"]},{"contextId":"u7_40_organise_gap_2","answer":"organise","wrong":["invent","decorate","translate"]},{"contextId":"u7_40_organise_gap_3","answer":"organise","wrong":["postpone","photograph","celebrate"]}],"spellingErrors":["organice","orgenise","organnise","organsie","oraganise","orgainse"],"wordFamilyForms":[{"form":"organise","partOfSpeech":"verb","example":"A teacher can help students to organise their revision into small topics.","pedagogicallyUseful":true},{"form":"organisation","partOfSpeech":"noun","example":"The organisation of the interview day was excellent, and nobody had to wait long.","pedagogicallyUseful":true,"altExample":"Good organisation makes it easier to finish projects before the deadline."},{"form":"organised","partOfSpeech":"adjective","example":"She is a very organised person who always keeps her notes in order.","pedagogicallyUseful":true,"altExample":"The conference was well organised, with a clear programme and plenty of helpers."}],"masteryPassages":[{"passageId":"u7_40_organise_passage_1","contextId":"u7_40_organise_gap_1","text":"The students had plenty of good ideas for their group presentation, but their first practice was confusing. Before the next rehearsal, they decided to ____ their ideas into a beginning, a middle and an end.","answer":"organise"},{"passageId":"u7_40_organise_passage_2","contextId":"u7_40_organise_gap_2","text":"The head teacher asked a group of Year 11 students to ____ a careers evening. They booked the hall, invited local employers and prepared a programme for the visitors.","answer":"organise"}],"contextDependentParaphrases":[],"wrongParaphrases":["to remove what is not needed","to make larger than before","to guess without evidence"],"misleadingDistractors":["to remove something that is no longer needed","to make something larger than before","to guess something without any evidence"],"teacherNote":"Verb: to arrange things in a sensible order, or to plan and prepare an event (organise your ideas, organise a meeting). British spelling: organise, with -ise. Boundary: organise is about putting things in order or planning them; it is not the same as order, which can mean to give a command. Related forms (organisation, organised, organiser) are taught in the Word Family pathway."}]'::jsonb,'["organisation","organised"]'::jsonb,'["organise your ideas","organise an event","organise your time"]'::jsonb,'live')
